CREATE TEMP TABLE unified_events(id text PRIMARY KEY,title text,status text,end_date timestamptz,image text);
CREATE TEMP TABLE unified_markets(id text PRIMARY KEY,event_id text,venue text,venue_market_id text,title text,category text,status text,resolved_outcome text,resolved_outcome_pct numeric,outcomes text,expiration_time timestamptz,close_time timestamptz,updated_at timestamptz,liquidity numeric,image text,description text,metadata jsonb);
CREATE TEMP TABLE polymarket_markets(id text PRIMARY KEY,accepting_orders boolean,active boolean,closed boolean,archived boolean);
CREATE TEMP TABLE unified_market_tokens(market_id text,outcome_side text,token_id text,updated_at timestamptz);
CREATE INDEX discovery_test_tokens ON unified_market_tokens(market_id);
CREATE TEMP TABLE unified_token_top_latest(token_id text PRIMARY KEY,best_bid numeric,best_ask numeric,ts timestamptz);
CREATE TEMP TABLE unified_market_activity_metrics_24h(market_id text PRIMARY KEY,venue text,volume_last_24h numeric,volume_valid boolean,liquidity_now numeric);
CREATE INDEX discovery_test_volume ON unified_market_activity_metrics_24h(volume_last_24h DESC) WHERE volume_valid;
CREATE TEMP TABLE ai_notes(id uuid PRIMARY KEY,source_id text,source_kind text,producer_type text,note_type text,status text,title text,description text,created_at timestamptz,lineage jsonb,metrics jsonb,model_meta jsonb);
CREATE INDEX discovery_test_public_notes ON ai_notes(created_at DESC,id DESC) WHERE producer_type='holder_research' AND source_kind='market' AND status<>'retracted' AND ((note_type='signal' AND metrics #>> '{publicationDecisionV1,status}'='PUBLISH' AND metrics #>> '{publicationDecisionV1,authority}'='holder_research_quality_gate') OR (note_type='context' AND metrics ? 'publicContextV1'));
CREATE INDEX discovery_test_market_notes ON ai_notes(source_id,created_at DESC,id DESC) WHERE producer_type='holder_research' AND source_kind='market' AND status<>'retracted' AND ((note_type='signal' AND metrics #>> '{publicationDecisionV1,status}'='PUBLISH' AND metrics #>> '{publicationDecisionV1,authority}'='holder_research_quality_gate') OR (note_type='context' AND metrics ? 'publicContextV1'));
CREATE TEMP TABLE wallets(id uuid PRIMARY KEY,address text,chain text,label text,metadata jsonb);
CREATE INDEX discovery_test_owner_address ON wallets(chain,lower(address));
CREATE INDEX discovery_test_owner_derived ON wallets((metadata->>'derivedFrom'),chain) WHERE metadata->>'kind'='safe_owner';
CREATE TEMP TABLE wallet_onchain_state(wallet_id uuid PRIMARY KEY,owner_wallet_id uuid);
CREATE TEMP TABLE wallet_profiles(wallet_id uuid PRIMARY KEY,profile jsonb);
CREATE TEMP TABLE wallet_intel_selector_snapshot(wallet_id uuid PRIMARY KEY,last_activity_at timestamptz,metrics_as_of timestamptz,metrics_pnl_30d numeric,metrics_resolved_edge_sample_count_30d integer,metrics_resolved_win_rate_edge_30d numeric,exposure_usd numeric,hedged_notional_usd numeric,hedge_ratio numeric,two_sided_markets integer);
CREATE INDEX discovery_test_wallet_activity ON wallet_intel_selector_snapshot(last_activity_at DESC);
CREATE TEMP TABLE wallet_position_exposure(wallet_id uuid PRIMARY KEY,open_positions_version integer,open_positions jsonb,as_of timestamptz);
CREATE TEMP TABLE wallet_position_snapshots(wallet_id uuid,venue text,market_id text,outcome_side text,shares numeric,size_usd numeric,snapshot_at timestamptz,metadata jsonb);
CREATE INDEX discovery_test_snapshots ON wallet_position_snapshots(wallet_id,venue,snapshot_at DESC);
CREATE INDEX discovery_test_snapshot_time ON wallet_position_snapshots(wallet_id,snapshot_at DESC);
CREATE TEMP TABLE wallet_activity_events(wallet_id uuid,venue text,market_id text,outcome_side text,delta_shares numeric,action text,occurred_at timestamptz,source text,activity_type text);
CREATE INDEX discovery_test_activity_events ON wallet_activity_events(wallet_id,activity_type,occurred_at DESC);

INSERT INTO unified_events SELECT 'e'||n,'Event '||n,'ACTIVE','2026-10-25T14:00Z',null FROM generate_series(1,150) n;
INSERT INTO unified_markets SELECT 'limitless:'||n,'e'||n,'limitless',n::text,'Outcome '||n,CASE WHEN n=150 THEN 'crypto' ELSE 'politics' END,'ACTIVE',null,null,'["Yes","No"]','2026-10-25T13:00Z',null,'2026-10-25T12:00Z',10000,null,'Official resolution rules','{}' FROM generate_series(1,150) n;
INSERT INTO unified_market_tokens SELECT 'limitless:'||n,side_row.side,side_row.side||n,'2026-10-25T12:00Z' FROM generate_series(1,150) n CROSS JOIN (VALUES ('YES'),('NO')) side_row(side);
INSERT INTO unified_token_top_latest SELECT side_row.side||n,CASE WHEN side_row.side='YES' THEN 0.93 ELSE 0.05 END,CASE WHEN side_row.side='YES' THEN 0.95 ELSE 0.07 END,'2026-10-25T12:00Z' FROM generate_series(1,150) n CROSS JOIN (VALUES ('YES'),('NO')) side_row(side);
INSERT INTO unified_market_activity_metrics_24h SELECT 'limitless:'||n,'limitless',2000,true,10000 FROM generate_series(1,150) n;
INSERT INTO wallets SELECT ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'0x'||lpad(n::text,40,'0'),'evm',null,'{}' FROM generate_series(1,4) n;
INSERT INTO wallet_intel_selector_snapshot SELECT id,'2026-10-25T12:00Z','2026-10-25T12:00Z',1000,30,0.1,1000,0,0,0 FROM wallets;
INSERT INTO wallet_position_snapshots SELECT id,'limitless','limitless:1','YES',500,450,'2026-10-25T12:00Z','{}' FROM wallets;
INSERT INTO wallet_activity_events SELECT id,'limitless','limitless:1','YES',5,'BUY','2026-10-25T11:00Z'::timestamptz+n*interval '1 second','snapshot_delta','delta' FROM wallets CROSS JOIN generate_series(1,120) n;
INSERT INTO wallet_activity_events SELECT id,'limitless','limitless:1','YES',100,'SELL','2026-10-25T11:30Z','snapshot_delta','delta' FROM wallets;
INSERT INTO wallet_activity_events SELECT id,'limitless','limitless:1','YES',10000,'BUY','2026-10-25T11:30Z','trade','trade' FROM wallets;
INSERT INTO wallet_position_exposure SELECT id,1,jsonb_build_array(jsonb_build_object('venue','limitless','marketId','limitless:1','outcomeSide','YES','shares',500,'sizeUsd',450,'snapshotAt','2026-10-25T12:00:00Z')),'2026-10-25T12:00Z' FROM wallets WHERE address LIKE '%1';
INSERT INTO ai_notes VALUES ('10000000-0000-4000-8000-000000000001','limitless:1','market','holder_research','signal','active','Research','Public thesis','2026-10-25T11:00Z','{"side":"YES"}','{"publicationDecisionV1":{"status":"PUBLISH","authority":"holder_research_quality_gate"},"hunchStrengthV1":{"grade":"strong"}}','{}');

CREATE TEMP TABLE ai_note_targets(note_id uuid,target_kind text,target_id text,target_rank integer,target_meta jsonb,PRIMARY KEY(note_id,target_kind,target_id));
CREATE TEMP TABLE polymarket_asset_bindings(chain_id integer,position_contract text,asset_id text,market_id text,protocol_version text,outcome_index integer,PRIMARY KEY(chain_id,position_contract,asset_id));
CREATE INDEX discovery_test_asset_id ON polymarket_asset_bindings(asset_id);
ALTER TABLE wallet_intel_selector_snapshot ADD COLUMN metrics_resolved_actual_win_rate_30d numeric DEFAULT 0.6;
ALTER TABLE wallet_intel_selector_snapshot ADD COLUMN metrics_resolved_expected_win_rate_30d numeric DEFAULT 0.5;
UPDATE wallet_position_snapshots SET metadata=jsonb_build_object('tokenId','YES1','positionContract','0xctf');
UPDATE ai_notes SET metrics=metrics||'{"socialInstrumentV1":{"marketId":"limitless:1","venue":"limitless","tokenId":"YES1","outcome":"YES","generation":"8453:0xctf:YES1","expiry":"2026-10-25T13:00:00.000Z"},"sides":{"YES":{"sharpUsd":1000},"NO":{"sharpUsd":0}}}'::jsonb;
INSERT INTO ai_note_targets VALUES ('10000000-0000-4000-8000-000000000001','wallet','00000000-0000-4000-8000-000000000001',10,'{"side":"YES"}');
